dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "region",
      "label": "Set region (chr:start-end)",
      "type": "input",
      "values": "kp genes",
      "convert to region": "true",
      "expand region by": 100000,
      "search point": "https://vision.hugeampkpnbi.org"
    }
  ],
  "sections": [
    {
      "section id": "variant_links_gene_sqtl",
      "header": "sQTLs: by Region",
      "data point": {
        "type": "bioindex",
        "url": "https://vision.hugeampkpnbi.org/api/bio/",
        "index": "variant-links",
        "parameters": [
          "region"
        ],
        "region": "region",
        "parameters type": "array",
        "data type": "bioindex"
      },
      "pre filters": [
        {
          "field": "Method",
          "value": "sQTLs",
          "type": "search"
        }
      ],
      "table format": {
        "data zoom": {
          "chromosome": "Chromosome",
          "position": "Position"
        },
        "star column": "Variant ID",
        "data convert": [
          {
            "type": "raw",
            "field name": "Chromosome",
            "raw field": "chromosome"
          },
          {
            "type": "raw",
            "field name": "Position",
            "raw field": "start"
          },
          {
            "type": "raw",
            "field name": "variant_links Position",
            "raw field": "start"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "QTL_beta"
          },
          {
            "type": "raw",
            "field name": "P-value",
            "raw field": "QTL_p"
          },
          {
            "type": "calculate",
            "field name": "-log10(P-value)",
            "raw field": "QTL_p",
            "calculation type": "-log10"
          },
          {
            "type": "raw",
            "field name": "Start",
            "raw field": "start"
          },
          {
            "type": "calculate",
            "field name": "End",
            "expression": [
              "end",
              "+",
              2
            ],
            "calculation type": "math"
          },
          {
            "type": "join multi",
            "field name": "Region",
            "fields to join": [
              "Start",
              "Start"
            ],
            "join by": [
              "-"
            ]
          },
          {
            "type": "raw",
            "field name": "Linked Genes",
            "raw field": "gene"
          },
          {
            "type": "raw",
            "field name": "Target Gene",
            "raw field": "gene"
          },
          {
            "type": "raw",
            "field name": "Tissue",
            "raw field": "tissue"
          },
          {
            "type": "raw",
            "field name": "Biosample",
            "raw field": "biosample"
          },
          {
            "type": "raw",
            "field name": "Method",
            "raw field": "method"
          },
          {
            "type": "raw",
            "field name": "Dataset",
            "raw field": "dataset"
          },
          {
            "type": "raw",
            "field name": "Source",
            "raw field": "source"
          },
          {
            "type": "raw",
            "field name": "State",
            "raw field": "state"
          },
          {
            "type": "raw",
            "field name": "Variant ID",
            "raw field": "variant"
          },
          {
            "type": "join multi",
            "field name": "Variant_tissue",
            "fields to join": [
              "Variant ID",
              "Tissue"
            ],
            "join by": [
              ":"
            ]
          },
          {
            "type": "raw",
            "field name": "Splice ID",
            "raw field": "splice_id"
          },
          {
            "type": "raw",
            "field name": "Cluster ID",
            "raw field": "cluster_id"
          },
          {
            "type": "join multi",
            "field name": "Splice event",
            "fields to join": [
              "splice_start",
              "splice_end"
            ],
            "join by": [
              "-"
            ]
          },
          {
            "type": "join multi",
            "field name": "Splice ID_Linked gene",
            "fields to join": [
              "Splice ID",
              "Linked Genes"
            ],
            "join by": [
              "_"
            ]
          }
        ],
        "top rows": [
          "Variant ID",
          "Linked Genes",
          "Tissue",
          "Biosample",
          "P-value",
          "Beta",
          "Cluster ID",
          "Splice ID",
          "Splice event",
          "Dataset",
          "Source",
          "State"
        ],
        "column formatting": {
          "Tissue": {
            "type": [
              "set parameter"
            ],
            "target sections": [
              {
                "section": "all",
                "label": "Set Tissue",
                "parameter": [
                  "tissue"
                ]
              }
            ]
          }
        }
      },
      "filters": [
        {
          "field": "Variant ID",
          "label": "Variant ID",
          "type": "search",
          "features": [
            "autocomplete"
          ]
        },
        {
          "field": "Tissue",
          "label": "Tissue",
          "type": "checkbox"
        },
        {
          "field": "Linked Genes",
          "label": "Linked Genes",
          "type": "checkbox"
        }
      ],
      "visualizers": {
        "wrapper type": "grouped tabs",
        "groups": [
          {
            "label": "A group",
            "visualizers": [
              {
                "label": "Annotated regions (grouped by Splice ID_Linked gene, colored by Cluster ID)",
                "type": "region track",
                "zoom": "true",
                "render by": "Region",
                "x axis field": "Position",
                "y axis field": "Splice ID_Linked gene",
                "hover content": [
                  "Variant ID",
                  "Biosample",
                  "Splice ID",
                  "Method",
                  "P-value",
                  "Beta",
                  "Dataset",
                  "Source",
                  "State"
                ],
                "color by": "Cluster ID",
                "track height": 12,
                "plot margin": {
                  "left": 200,
                  "right": 200,
                  "top": 30,
                  "bottom": 100,
                  "bump": 10
                },
                "genome reference": "GRCh38"
              },
              {
                "label": "Annotated regions (grouped by tissues, colored by linked genes)",
                "type": "region track",
                "zoom": "true",
                "render by": "Region",
                "x axis field": "Position",
                "y axis field": "Tissue",
                "hover content": [
                  "Variant ID",
                  "Biosample",
                  "Splice ID",
                  "Method",
                  "P-value",
                  "Beta",
                  "Dataset",
                  "Source",
                  "State"
                ],
                "color by": "Linked Genes",
                "track height": 12,
                "plot margin": {
                  "left": 200,
                  "right": 200,
                  "top": 30,
                  "bottom": 100,
                  "bump": 10
                },
                "genome reference": "GRCh38"
              }
            ]
          },
          {
            "label": "B group",
            "visualizers": [
              {
                "label": "Annotated regions (grouped by tissues, colored by Splice ID)",
                "type": "region track",
                "zoom": "true",
                "render by": "Region",
                "x axis field": "Position",
                "y axis field": "Tissue",
                "hover content": [
                  "Variant ID",
                  "Biosample",
                  "Method",
                  "P-value",
                  "Beta",
                  "Dataset",
                  "Source",
                  "State"
                ],
                "color by": "Splice ID",
                "track height": 12,
                "plot margin": {
                  "left": 200,
                  "right": 200,
                  "top": 30,
                  "bottom": 100,
                  "bump": 10
                },
                "genome reference": "GRCh38"
              },
              {
                "label": "Annotated regions (grouped by linked genes, colored by tissues)",
                "type": "region track",
                "zoom": "true",
                "render by": "Region",
                "x axis field": "Position",
                "y axis field": "Linked Genes",
                "hover content": [
                  "Variant ID",
                  "Biosample",
                  "Method",
                  "P-value",
                  "Beta",
                  "Dataset",
                  "Source",
                  "State"
                ],
                "color by": "Tissue",
                "track height": 12,
                "plot margin": {
                  "left": 200,
                  "right": 200,
                  "top": 30,
                  "bottom": 100,
                  "bump": 10
                }
              },
              {
                "label": "Annotated regions (grouped by linked genes, colored by Splice ID)",
                "type": "region track",
                "zoom": "true",
                "render by": "Region",
                "x axis field": "Position",
                "y axis field": "Linked Genes",
                "hover content": [
                  "Variant ID",
                  "Biosample",
                  "Splice ID",
                  "Method",
                  "P-value",
                  "Beta",
                  "Dataset",
                  "Source",
                  "State"
                ],
                "color by": "Splice ID",
                "track height": 12,
                "plot margin": {
                  "left": 200,
                  "right": 200,
                  "top": 30,
                  "bottom": 100,
                  "bump": 10
                }
              },
              {
                "label": "Splicing region (grouped by linked genes, colored by tissues)",
                "type": "region track",
                "zoom": "true",
                "render by": "Splice event",
                "x axis field": "Position",
                "y axis field": "Linked Genes",
                "hover content": [
                  "Variant ID",
                  "Biosample",
                  "Splice event",
                  "P-value",
                  "Beta",
                  "Dataset",
                  "Source",
                  "State"
                ],
                "color by": "Tissue",
                "track height": 12,
                "plot margin": {
                  "left": 200,
                  "right": 200,
                  "top": 30,
                  "bottom": 100,
                  "bump": 10
                }
              },
              {
                "label": "Rendered by variants",
                "star key": "Variant ID",
                "zoom": "true",
                "type": "region plot",
                "genome reference": "GRCh38",
                "x axis field": "Position",
                "y axis field": "-log10(P-value)",
                "render by": "Variant_tissue",
                "y axis label": "-Log10(p-value)",
                "x axis label": "Chromosome",
                "hover content": [
                  "P-value",
                  "Beta"
                ],
                "height": 120,
                "plot margin": {
                  "left": 200,
                  "right": 100,
                  "top": 30,
                  "bottom": 100,
                  "bump": 10
                },
                "ld server": {
                  "pos": "Position",
                  "ref": "ref",
                  "alt": "alt",
                  "ref variant field": "Variant ID",
                  "populations field": "P-value",
                  "populations type": "fixed",
                  "fixed population": "ALL",
                  "populations": {
                    "ALL": "ALL"
                  }
                },
                "genes track": {
                  "input type": "dynamic",
                  "dynamic parameter": "region",
                  "search point": "https://vision.hugeampkpnbi.org"
                },
                "input type": "dynamic",
                "dynamic parameter": "region",
                "if combine y axis field": {
                  "type": "average",
                  "field": "-log10(P-value)"
                }
              }
            ]
          }
        ]
      }
    }
  ]
}
